const input = $json.body ?? $json;

const errors = [];

const validPriorities = [
  'Critical',
  'High',
  'Medium',
  'Low'
];

function isValidDate(value) {
  return /^\d{4}-\d{2}-\d{2}$/.test(value || '');
}

function isMonday(dateString) {
  const d = new Date(`${dateString}T00:00:00Z`);
  return d.getUTCDay() === 1;
}

function isNonNegativeNumber(value) {
  return (
    typeof value === 'number' &&
    Number.isFinite(value) &&
    value >= 0
  );
}

// ------------------------
// Project
// ------------------------

if (!input.project) {
  errors.push('project object is required');
} else {
  if (!/^PRJ-\d{3}$/.test(input.project.project_id || '')) {
    errors.push(
      'project.project_id must follow PRJ-###'
    );
  }

  if (!input.project.project_name) {
    errors.push(
      'project.project_name is required'
    );
  }

  if (!validPriorities.includes(input.project.priority)) {
    errors.push(
      'project.priority must be Critical, High, Medium or Low'
    );
  }

  if (!isValidDate(input.project.start_date)) {
    errors.push(
      'project.start_date must use YYYY-MM-DD'
    );
  }

  if (!isValidDate(input.project.end_date)) {
    errors.push(
      'project.end_date must use YYYY-MM-DD'
    );
  }

  if (
    isValidDate(input.project.start_date) &&
    isValidDate(input.project.end_date) &&
    input.project.end_date < input.project.start_date
  ) {
    errors.push(
      'project.end_date cannot be before start_date'
    );
  }
}

// ------------------------
// Resource
// ------------------------

if (!input.resource) {
  errors.push('resource object is required');
} else {
  if (!/^RES-\d{3}$/.test(input.resource.resource_id || '')) {
    errors.push(
      'resource.resource_id must follow RES-###'
    );
  }

  if (!input.resource.resource_name) {
    errors.push(
      'resource.resource_name is required'
    );
  }

  if (!input.resource.role) {
    errors.push(
      'resource.role is required'
    );
  }

  if (!input.resource.department) {
    errors.push(
      'resource.department is required'
    );
  }

  if (
    !isNonNegativeNumber(
      input.resource.standard_weekly_hours
    )
  ) {
    errors.push(
      'resource.standard_weekly_hours must be a non-negative number'
    );
  }
}

// ------------------------
// Capacity
// ------------------------

if (!input.capacity) {
  errors.push('capacity object is required');
} else {
  if (!isValidDate(input.capacity.week_start_date)) {
    errors.push(
      'capacity.week_start_date must use YYYY-MM-DD'
    );
  } else if (!isMonday(input.capacity.week_start_date)) {
    errors.push(
      'capacity.week_start_date must be a Monday'
    );
  }

  const capacityFields = [
    'standard_hours',
    'leave_hours',
    'holiday_hours',
    'training_hours',
    'bau_hours'
  ];

  for (const field of capacityFields) {
    if (
      !isNonNegativeNumber(
        input.capacity[field]
      )
    ) {
      errors.push(
        `capacity.${field} must be a non-negative number`
      );
    }
  }
}

// ------------------------
// Demand
// ------------------------

if (
  !Array.isArray(input.demand) ||
  input.demand.length === 0
) {
  errors.push(
    'demand must contain at least one activity'
  );
} else {
  input.demand.forEach((d, index) => {
    if (!/^PRJ-\d{3}$/.test(d.project_id || '')) {
      errors.push(
        `demand[${index}].project_id must follow PRJ-###`
      );
    }

    if (!d.activity_name) {
      errors.push(
        `demand[${index}].activity_name is required`
      );
    }

    if (!isNonNegativeNumber(d.planned_hours)) {
      errors.push(
        `demand[${index}].planned_hours must be a non-negative number`
      );
    }

    if (!validPriorities.includes(d.priority)) {
      errors.push(
        `demand[${index}].priority must be Critical, High, Medium or Low`
      );
    }

    if (typeof d.critical_path !== 'boolean') {
      errors.push(
        `demand[${index}].critical_path must be true or false`
      );
    }
  });
}

// ------------------------
// Final output
// ------------------------

if (errors.length > 0) {
  return {
    json: {
      validation_status: 'FAILED',
      valid: false,
      error_count: errors.length,
      errors,
      original_payload: input
    }
  };
}

return {
  json: {
    validation_status: 'PASSED',
    valid: true,
    error_count: 0,
    errors: [],
    payload: input
  }
};

const normalized =
  $items("Normalize Planning Data")[0].json;

return normalized.demand.map(d => ({
  json: {
    resource_id:
      d.resource_id,

    project_id:
      d.project_id,

    week_start_date:
      d.week_start_date,

    activity_name:
      d.activity_name,

    planned_hours:
      d.planned_hours,

    priority:
      d.priority,

    critical_path:
      d.critical_path
  }
}));

const normalized =
  $items("Normalize Planning Data")[0].json;

return [{
  json: {
    resource_id:
      normalized.resource.resource_id,

    week_start_date:
      normalized.capacity.week_start_date,

    demand_records_processed:
      $input.all().length
  }
}];

const normalized =
  $items("Normalize Planning Data")[0].json;

const conflictItems =
  $items("Recalculate Capacity Conflicts");

const conflict =
  conflictItems.length > 0
    ? conflictItems[0].json
    : null;

const availableHours =
  normalized.capacity.standard_hours
  - normalized.capacity.leave_hours
  - normalized.capacity.holiday_hours
  - normalized.capacity.training_hours
  - normalized.capacity.bau_hours;

const totalDemand =
  normalized.demand.reduce(
    (sum, d) =>
      sum + Number(d.planned_hours),
    0
  );

return [{
  json: {
    intake_status:
      'COMPLETED',

    project: {
      project_id:
        normalized.project.project_id,

      project_name:
        normalized.project.project_name
    },

    resource: {
      resource_id:
        normalized.resource.resource_id,

      resource_name:
        normalized.resource.resource_name,

      role:
        normalized.resource.role,

      department:
        normalized.resource.department
    },

    capacity: {
      week_start_date:
        normalized.capacity.week_start_date,

      standard_hours:
        normalized.capacity.standard_hours,

      leave_hours:
        normalized.capacity.leave_hours,

      holiday_hours:
        normalized.capacity.holiday_hours,

      training_hours:
        normalized.capacity.training_hours,

      bau_hours:
        normalized.capacity.bau_hours,

      available_hours:
        availableHours
    },

    demand: {
      activities_processed:
        normalized.demand.length,

      total_planned_hours:
        totalDemand
    },

    conflict_detected:
      conflict !== null,

    conflict:
      conflict
        ? {
            conflict_id:
              conflict.conflict_id,

            utilization_pct:
              Number(
                conflict.utilization_pct
              ),

            overallocation_hours:
              Number(
                conflict.overallocation_hours
              ),

            severity:
              conflict.severity,

            status:
              conflict.status
          }
        : null
  }
}];
